// TH15 synthetic aliases, copied from transcribe/th15/touhou-bullets.ecl.
// Source ECir02_at1 uses etSprite(0, 8, 6): TH15 type8 rice, color 6.
const TH15_RICE: int = 480;

// TH15 v1.00b Stage 4 mid-stage wave: st04.ecl.txt MainSub02 (1087-1152).
// Six rows of ten ECir02 enemies enter from the sides and curve through 180 deg.
// Source enmCreate x/y are relative to the stage root (MainFront runs on the
// stage task at (0,0)), so they are used as absolute world coordinates here.

const TIME_LIMIT: int = 1624;   // 120 opening + 1500 schedule/tail estimate + 4 startup
const OPENING_BUFFER: int = 120;

// ECir02 (st04.ecl.txt:187-211). No moveLimit in source; hitbox/hurtbox are
// setHurtbox(24,24) -> r12 and setHitbox(16,16) -> r8 (circle branch, width*0.5).
// anm*/drop*/setDeath and the dead-attack callback are omitted: approved visual
// and drop simplification, and the invulnerable shell keeps the survival path.
async sub ecir02(dir: angle, turn: angle) {
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);
    move_vel(0, dir, 5fx, EASE_LINEAR);      // moveVel(%F0, 5.0f)
    spawn ecir02_attack();                   // @ECir02_at1() async
    wait(50);                                // wait($I0), I0 = 50
    var a: angle = dir;
    for i in 0..60 {                         // moveAngleTime(60, 7, %F1)
        wait(1);                             // mode 7 = +%F1 per movement tick
        a = a + turn;
        move_angle(0, a, EASE_LINEAR);
    }
    loop { wait(1000); }                     // source tail: wait(1000) loop
}

// ECir02_at1 (st04.ecl.txt:249-289), etAim(0,1) 1x1 fixed fan.
// The single bullet is aimed at the player plus %RANDF2*10deg, fired every
// gap frames, count times. ANIM EX (type 2, a=1) keeps its birth shift
// position -= 4*velocity even though the birth animation itself is omitted.
async sub ecir02_attack() {
    var rank: int = global(GVAR_RANK);
    var speed: fx = 3fx;                     // !E / !N
    var count: int = 20;
    var gap: int = 20;
    if rank == 1 {
        count = 40;
        gap = 10;
    } else if rank == 2 {
        count = 50;
        gap = 8;
        speed = 4fx;
    } else if rank >= 3 {
        count = 80;
        gap = 6;
        speed = 5fx;
    }
    wait(rand(65536) % 40);                  // wait($RAND % 40)
    for i in 0..count {
        var off: int = ((rand(65536) - 32768) * 1820) / 32768;  // ±10deg in BAM
        var ang: angle = aim_player() + (off as angle);
        var vx: fx = speed * cos(ang);
        var vy: fx = speed * sin(ang);
        _ = fire(TH15_RICE, 6, $self_x - 4fx * vx, $self_y - 4fx * vy,
                 speed, ang, none, none);
        wait(gap);
    }
}

// MainSub02 spawn schedule: wait(120), then six rows of ten at 10-frame gaps.
async sub pattern() {
    wait(OPENING_BUFFER);
    wait(120);                               // MainSub02:1090 wait(120)
    for i1 in 0..10 {                         // row A: F0=0.0,  F1=+0.05236
        _ = spawn_enemy(-224fx, 64fx, 80, 0, 1000, 0, ecir02(0deg, 3deg));
        wait(10);
    }
    for i2 in 0..10 {                         // row B: F0=pi,   F1=-0.05236
        _ = spawn_enemy(224fx, 80fx, 80, 0, 1000, 0, ecir02(180deg, -3deg));
        wait(10);
    }
    for i3 in 0..10 {                         // row C: F0=-0.19635, F1=+0.05236
        _ = spawn_enemy(-224fx, 96fx, 80, 0, 1000, 0, ecir02(-2048bam, 3deg));
        wait(10);
    }
    for i4 in 0..10 {                         // row D: F0=-2.945243, F1=-0.05236
        _ = spawn_enemy(224fx, 112fx, 80, 0, 1000, 0, ecir02(-30720bam, -3deg));
        wait(10);
    }
    for i5 in 0..10 {                         // row E: F0=-0.785398, F1=+0.05236
        _ = spawn_enemy(-224fx, 240fx, 80, 0, 1000, 0, ecir02(-45deg, 3deg));
        wait(10);
    }
    for i6 in 0..10 {                         // row F: F0=-2.356194, F1=-0.05236
        _ = spawn_enemy(224fx, 240fx, 80, 0, 1000, 0, ecir02(-135deg, -3deg));
        wait(10);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
